// Find the viewer count text from the thumbnail overlay in this card
var imageLink = element.querySelector('.preview-card-image-link');
if (!imageLink) return;

var viewerStat = imageLink.querySelector('.tw-media-card-stat');
if (!viewerStat) return;

var viewerText = viewerStat.textContent.trim();
if (!viewerText) return;

// Find the streamer name container
var nameContainer = element.querySelector('.lvgXe');
if (!nameContainer) return;

// Check if we already added a viewer count line (idempotency)
var existingViewerLine = nameContainer.querySelector('[data-viewer-count-added]');
if (existingViewerLine) {
    existingViewerLine.textContent = viewerText;
    return;
}

// Create the new viewer count element
var viewerLine = document.createElement('p');
viewerLine.setAttribute('data-viewer-count-added', 'true');
viewerLine.textContent = viewerText;
viewerLine.style.cssText = 'font-size:14px;color:#adadb8;margin-top:2px;font-weight:500;';

// Insert after the streamer name (which is inside lvgXe, before the verified badge)
var parent = nameContainer.parentElement; // .lfuVkX
parent.insertBefore(viewerLine, nameContainer.nextSibling);
